screenPanels.initJs:
function(container, apiUrl, tables) {
  const errorTable = tables[0]; // エラーログテーブル
  const validationTable = tables[1]; // バリデーション結果テーブル
  const errorClassTable = tables[2]; // エラー分類マスタ
  const assigneeTable = tables[3]; // 責任者マスタ

  let allErrors = [];
  let selectedErrorId = null;

  // ===== 1. 再描画関数 =====
  function renderErrors(errors) {
    const tbody = container.querySelector("#error-tbody");
    if (!errors || errors.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--text-muted);">エラーがありません</td></tr>';
      return;
    }
    tbody.innerHTML = errors.map(err => {
      const severity = err.重要度 || 'INFO';
      const status = err.ステータス || '未対応';
      const severityColor = severity === 'CRITICAL' ? '#e74c3c' : severity === 'ERROR' ? '#e67e22' : severity === 'WARNING' ? '#f39c12' : '#3498db';
      const statusBg = status === '解決済み' ? 'rgba(39,174,96,0.2)' : status === '対応中' ? 'rgba(52,152,219,0.2)' : 'rgba(231,76,60,0.2)';
      return `<tr data-id="${err.id}" style="cursor:pointer;border-bottom:1px solid rgba(255,255,255,0.05);hover:background:rgba(255,255,255,0.05);">
        <td style="padding:8px;color:var(--text);">${err.受注データID?.substring(0,8) || '-'}</td>
        <td style="padding:8px;color:var(--text);">${err.エラーコード || '-'}</td>
        <td style="padding:8px;color:var(--text);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${err.エラーメッセージ || '-'}</td>
        <td style="padding:8px;text-align:center;"><span style="background:${severityColor};color:#fff;padding:2px 6px;border-radius:2px;font-size:11px;">${severity}</span></td>
        <td style="padding:8px;text-align:center;"><span style="background:${statusBg};color:var(--text);padding:2px 6px;border-radius:2px;font-size:11px;">${status}</span></td>
        <td style="padding:8px;text-align:center;color:var(--text-muted);font-size:11px;">${new Date(err.作成日時).toLocaleDateString()}</td>
      </tr>`;
    }).join('');
  }

  // ===== 2. KPI 更新 =====
  function updateKPIs(errors) {
    const pending = errors.filter(e => e.ステータス === '未対応').length;
    const critical = errors.filter(e => e.重要度 === 'CRITICAL').length;
    const today = new Date().toLocaleDateString();
    const todayCount = errors.filter(e => new Date(e.作成日時).toLocaleDateString() === today).length;
    const resolved = errors.filter(e => e.ステータス === '解決済み').length;
    const rate = errors.length > 0 ? Math.round((resolved / errors.length) * 100) : 0;

    container.querySelector('[data-testid="kpi-pending-errors"]').textContent = pending;
    container.querySelector('[data-testid="kpi-critical-errors"]').textContent = critical;
    container.querySelector('[data-testid="kpi-today-validations"]').textContent = todayCount;
    container.querySelector('[data-testid="kpi-resolution-rate"]').textContent = rate + '%';
  }

  // ===== 3. グラフ初期化 =====
  function initCharts(errors) {
    // 重要度別分布
    const severityMap = {};
    errors.forEach(e => {
      const sev = e.重要度 || 'INFO';
      severityMap[sev] = (severityMap[sev] || 0) + 1;
    });
    const severityLabels = Object.keys(severityMap);
    const severityData = Object.values(severityMap);

    const ctxSeverity = container.querySelector('#chart-severity').getContext('2d');
    new window.Chart(ctxSeverity, {
      type: 'doughnut',
      data: {
        labels: severityLabels,
        datasets: [{
          data: severityData,
          backgroundColor: ['#e74c3c', '#e67e22', '#f39c12', '#3498db'],
          borderColor: 'rgba(0,0,0,0.3)',
          borderWidth: 1
        }]
      },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { color: '#9fb0d1', font: { size: 11 } } } } }
    });

    // ステータス別推移（簡易版）
    const statusMap = {};
    errors.forEach(e => {
      const st = e.ステータス || '未対応';
      statusMap[st] = (statusMap[st] || 0) + 1;
    });
    const statusLabels = Object.keys(statusMap);
    const statusData = Object.values(statusMap);

    const ctxStatus = container.querySelector('#chart-status').getContext('2d');
    new window.Chart(ctxStatus, {
      type: 'bar',
      data: {
        labels: statusLabels,
        datasets: [{
          label: 'エラー件数',
          data: statusData,
          backgroundColor: '#d4a574',
          borderColor: '#d4a574',
          borderWidth: 1
        }]
      },
      options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { ticks: { color: '#9fb0d1', font: { size: 10 } } }, y: { ticks: { color: '#9fb0d1', font: { size: 10 } } } } }
    });
  }

  // ===== 4. 詳細パネル表示 =====
  function showDetail(errorId) {
    selectedErrorId = errorId;
    const error = allErrors.find(e => e.id === errorId);
    if (!error) return;

    container.querySelector('#detail-empty').style.display = 'none';
    container.querySelector('#detail-panel').style.display = 'block';

    container.querySelector('#detail-order-id').textContent = error.受注データID || '-';
    container.querySelector('#detail-error-code').textContent = error.エラーコード || '-';
    container.querySelector('#detail-error-msg').textContent = error.エラーメッセージ || '-';
    container.querySelector('#detail-error-detail').textContent = error.エラー詳細 || '（詳細なし）';
    container.querySelector('#detail-severity').textContent = error.重要度 || 'INFO';
    container.querySelector('#detail-status').value = error.ステータス || '未対応';
    container.querySelector('#detail-assignee').value = error.対応者ID || '';
    container.querySelector('#detail-comment').value = error.対応コメント || '';
  }

  // ===== 5. 初期データ読み込み =====
  async function loadErrors() {
    const rows = await window.aivicApi.list(0);
    allErrors = rows || [];
    renderErrors(allErrors);
    updateKPIs(allErrors);
    if (window.Chart) initCharts(allErrors);
  }

  // ===== 6. 検索フィルタ =====
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderNo = container.querySelector('#filter-order-no').value.toLowerCase();
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;
    const errorClass = container.querySelector('#filter-error-class').value;

    let filtered = allErrors;
    if (orderNo) filtered = filtered.filter(e => (e.受注データID || '').toLowerCase().includes(orderNo));
    if (severity) filtered = filtered.filter(e => e.重要度 === severity);
    if (status) filtered = filtered.filter(e => e.ステータス === status);
    if (errorClass) filtered = filtered.filter(e => e.エラー種別 === errorClass);

    renderErrors(filtered);
  });

  // ===== 7. バリデーション実行 =====
  container.querySelector('#btn-validate').addEventListener('click', async () => {
    alert('バリデーション実行処理を開始します（実装予定）');
    // 実装: 基幹システム連携画面へ遷移
    // window.showScreen('scr-1781408509581');
  });

  // ===== 8. エラー行クリック =====
  container.addEventListener('click', e => {
    const row = e.target.closest('tr[data-id]');
    if (row) {
      const errorId = row.dataset.id;
      showDetail(errorId);
    }
  });

  // ===== 9. エラー更新 =====
  container.querySelector('#btn-update-error').addEventListener('click', async () => {
    if (!selectedErrorId) return;
    const status = container.querySelector('#detail-status').value;
    const assignee = container.querySelector('#detail-assignee').value;
    const comment = container.querySelector('#detail-comment').value;

    const updated = await window.aivicApi.update(0, selectedErrorId, {
      ステータス: status,
      対応者ID: assignee,
      対応コメント: comment
    });

    if (updated) {
      alert('エラー情報を更新しました');
      await loadErrors();
      showDetail(selectedErrorId);
    }
  });

  // ===== 10. 通知送信 =====
  container.querySelector('#btn-notify').addEventListener('click', async () => {
    if (!selectedErrorId) return;
    const assignee = container.querySelector('#detail-assignee').value;
    if (!assignee) {
      alert('責任者を選択してください');
      return;
    }
    alert(`${assignee} に通知を送信しました`);
    // 実装: 通知履歴テーブルへ保存
  });

  // ===== 11. ログ表示 =====
  container.querySelector('#btn-view-log').addEventListener('click', () => {
    if (!selectedErrorId) return;
    const error = allErrors.find(e => e.id === selectedErrorId);
    const logContent = `[${new Date(error.作成日時).toISOString()}] エラーコード: ${error.エラーコード}\n${error.エラー詳細 || '（ログなし）'}`;
    container.querySelector('#log-content').textContent = logContent;
    container.querySelector('#modal-log').removeAttribute('hidden');
  });

  container.querySelector('#btn-close-log').addEventListener('click', () => {
    container.querySelector('#modal-log').setAttribute('hidden', '');
  });

  // ===== 12. ルール確認 =====
  container.querySelector('#btn-view-rule').addEventListener('click', () => {
    if (!selectedErrorId) return;
    alert('バリデーションルール確認画面へ遷移します（実装予定）');
    // window.showScreen('scr-1781408467707');
  });

  // ===== 初期化 =====
  loadErrors();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-log-tbody");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");
  const closeDetailBtn = container.querySelector("#close-detail-modal");
  const detailCloseBtn = container.querySelector("[data-testid='detail-close-button']");
  const detailMarkResolvedBtn = container.querySelector("[data-testid='detail-mark-resolved-button']");

  let currentDetailId = null;
  let allLogs = [];

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const severity = r.重要度 || r.severity || "WARNING";
      const severityColor = severity === "CRITICAL" ? "#ff4444" : severity === "ERROR" ? "#ff6a00" : "#ffa500";
      const statusColor = r.ステータス === "解決済み" ? "#4ade80" : r.ステータス === "対応中" ? "#60a5fa" : "#ef4444";

      return `
        <tr data-id="${r.id || r.エラーログID}" style="border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 0.75rem; color: var(--text); font-family: monospace; font-size: 0.8rem;">${(r.id || r.エラーログID || "").substring(0, 8)}</td>
          <td style="padding: 0.75rem; color: var(--text);">${r.受注ID || r.order_id || "-"}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.8rem;">${r.発生日時 ? new Date(r.発生日時).toLocaleString("ja-JP") : "-"}</td>
          <td style="padding: 0.75rem; color: var(--text); font-weight: 600;">${r.エラーコード || r.error_code || "-"}</td>
          <td style="padding: 0.75rem;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${severityColor}20; color: ${severityColor}; font-size: 0.75rem; font-weight: 600;">${severity}</span>
          </td>
          <td style="padding: 0.75rem;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${statusColor}20; color: ${statusColor}; font-size: 0.75rem; font-weight: 600;">${r.ステータス || r.status || "未対応"}</span>
          </td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="detail-btn" data-id="${r.id || r.エラーログID}" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); padding: 0.375rem 0.75rem; border-radius: 0.25rem; font-size: 0.75rem; cursor: pointer;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    allLogs = tables[0].records;
    renderRows(allLogs);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;
    const dateTo = container.querySelector("[data-testid='filter-date-to']").value;
    const errorCode = container.querySelector("[data-testid='filter-error-code']").value;
    const orderId = container.querySelector("[data-testid='filter-order-id']").value;
    const channel = container.querySelector("[data-testid='filter-channel']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;

    let filtered = allLogs;

    if (dateFrom) {
      const fromTime = new Date(dateFrom).getTime();
      filtered = filtered.filter(r => new Date(r.発生日時 || r.created_at).getTime() >= fromTime);
    }
    if (dateTo) {
      const toTime = new Date(dateTo).getTime();
      filtered = filtered.filter(r => new Date(r.発生日時 || r.created_at).getTime() <= toTime);
    }
    if (errorCode) {
      filtered = filtered.filter(r => (r.エラーコード || r.error_code || "").includes(errorCode));
    }
    if (orderId) {
      filtered = filtered.filter(r => (r.受注ID || r.order_id || "").includes(orderId));
    }
    if (channel) {
      filtered = filtered.filter(r => (r.チャネル || r.channel || "").includes(channel));
    }
    if (status) {
      filtered = filtered.filter(r => (r.ステータス || r.status || "未対応") === status);
    }

    renderRows(filtered);
  });

  // 4. 更新ボタン
  container.querySelector("[data-testid='refresh-button']").addEventListener("click", async () => {
    const result = await window.aivicApi.list(0);
    if (result) {
      allLogs = result;
      renderRows(allLogs);
    }
  });

  // 5. CSVエクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", () => {
    if (allLogs.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["ログID", "受注ID", "発生日時", "エラーコード", "エラーメッセージ", "重要度", "ステータス"];
    const rows = allLogs.map(r => [
      (r.id || r.エラーログID || "").substring(0, 8),
      r.受注ID || r.order_id || "",
      r.発生日時 ? new Date(r.発生日時).toLocaleString("ja-JP") : "",
      r.エラーコード || r.error_code || "",
      (r.エラーメッセージ || r.error_message || "").replace(/"/g, '""'),
      r.重要度 || r.severity || "",
      r.ステータス || r.status || ""
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(c => `"${c}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `error-logs-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 6. 詳細表示
  function showDetail(logId) {
    const log = allLogs.find(r => (r.id || r.エラーログID) === logId);
    if (!log) return;

    currentDetailId = logId;
    detailContent.innerHTML = `
      <div style="grid-column: 1 / -1;">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">ログID</label>
            <div style="color: var(--text); font-family: monospace; font-size: 0.9rem; margin-top: 0.25rem;">${log.id || log.エラーログID || "-"}</div>
          </div>
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">受注ID</label>
            <div style="color: var(--text); font-size: 0.9rem; margin-top: 0.25rem;">${log.受注ID || log.order_id || "-"}</div>
          </div>
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">発生日時</label>
            <div style="color: var(--text); font-size: 0.9rem; margin-top: 0.25rem;">${log.発生日時 ? new Date(log.発生日時).toLocaleString("ja-JP") : "-"}</div>
          </div>
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">エラーコード</label>
            <div style="color: var(--text); font-weight: 600; font-size: 0.9rem; margin-top: 0.25rem;">${log.エラーコード || log.error_code || "-"}</div>
          </div>
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">重要度</label>
            <div style="color: var(--text); font-size: 0.9rem; margin-top: 0.25rem;">${log.重要度 || log.severity || "-"}</div>
          </div>
          <div>
            <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">ステータス</label>
            <div style="color: var(--text); font-size: 0.9rem; margin-top: 0.25rem;">${log.ステータス || log.status || "未対応"}</div>
          </div>
        </div>
        <div style="margin-top: 1rem;">
          <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">エラーメッセージ</label>
          <div style="color: var(--text); font-size: 0.9rem; margin-top: 0.25rem; background: rgba(0,0,0,0.25); padding: 0.75rem; border-radius: 0.375rem; word-break: break-word;">${log.エラーメッセージ || log.error_message || "-"}</div>
        </div>
        <div style="margin-top: 1rem;">
          <label style="font-size: 0.75rem; color: var(--text-muted); font-weight: 500;">エラー詳細</label>
          <div style="color: var(--text-muted); font-size: 0.85rem; margin-top: 0.25rem; background: rgba(0,0,0,0.25); padding: 0.75rem; border-radius: 0.375rem; word-break: break-word; font-family: monospace; max-height: 200px; overflow-y: auto;">${log.エラー詳細 || log.error_detail || "-"}</div>
        </div>
      </div>
    `;
    detailModal.removeAttribute("hidden");
  }

  // 7. 詳細パネル操作
  closeDetailBtn.addEventListener("click", () => detailModal.setAttribute("hidden", ""));
  detailCloseBtn.addEventListener("click", () => detailModal.setAttribute("hidden", ""));

  detailMarkResolvedBtn.addEventListener("click", async () => {
    if (!currentDetailId) return;
    const result = await window.aivicApi.update(0, currentDetailId, { ステータス: "解決済み", status: "解決済み" });
    if (result) {
      const idx = allLogs.findIndex(r => (r.id || r.エラーログID) === currentDetailId);
      if (idx >= 0) {
        allLogs[idx].ステータス = "解決済み";
        allLogs[idx].status = "解決済み";
      }
      renderRows(allLogs);
      detailModal.setAttribute("hidden", "");
      alert("ステータスを更新しました");
    }
  });

  // 8. イベントデリゲーション（詳細ボタン）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });
}

function(container, apiUrl, tables) {
  const errorTbody = container.querySelector("#error-tbody");
  const detailModal = container.querySelector("#detail-modal");
  const commentModal = container.querySelector("#comment-modal");
  const detailContent = container.querySelector("#detail-content");

  let allErrors = [];
  let selectedErrorId = null;

  // 1. KPI 更新関数
  function updateKpis(errors) {
    const unresolved = errors.filter(e => e.ステータス === "未対応").length;
    const today = new Date().toISOString().split('T')[0];
    const todayErrors = errors.filter(e => e.発生日時?.startsWith(today)).length;
    const inProgress = errors.filter(e => e.ステータス === "対応中").length;
    const resolved = errors.filter(e => e.ステータス === "解決済み").length;

    container.querySelector("[data-testid='kpi-unresolved']").textContent = unresolved;
    container.querySelector("[data-testid='kpi-today']").textContent = todayErrors;
    container.querySelector("[data-testid='kpi-in-progress']").textContent = inProgress;
    container.querySelector("[data-testid='kpi-resolved']").textContent = resolved;
  }

  // 2. テーブル再描画関数
  function renderRows(errors) {
    if (!errors || errors.length === 0) {
      errorTbody.innerHTML = '<tr style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="9" style="padding: 20px; text-align: center; color: var(--text-muted);">該当するエラーがありません</td></tr>';
      updateKpis([]);
      return;
    }

    errorTbody.innerHTML = errors.map(err => {
      const priorityColor = {
        'CRITICAL': '#ff6a00',
        'ERROR': 'var(--primary)',
        'WARNING': '#fbbf24',
        'INFO': '#4a9eff'
      }[err.重要度] || 'var(--text-muted)';

      const statusBg = {
        '未対応': 'rgba(255, 106, 0, 0.15)',
        '対応中': 'rgba(74, 158, 255, 0.15)',
        '解決済み': 'rgba(74, 222, 128, 0.15)'
      }[err.ステータス] || 'transparent';

      const statusColor = {
        '未対応': '#ff6a00',
        '対応中': '#4a9eff',
        '解決済み': '#4ade80'
      }[err.ステータス] || 'var(--text)';

      return `<tr data-id="${err.id}" style="background: var(--bg-card); border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='var(--bg-card)'">
        <td style="padding: 8px; color: var(--text-muted); font-family: monospace; font-size: 12px;">${(err.id || '').substring(0, 8)}</td>
        <td style="padding: 8px; color: var(--text);">${err.受注番号 || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${err.エラー種別 || '-'}</td>
        <td style="padding: 8px; color: var(--text); max-width: 300px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" title="${err.エラーメッセージ || ''}">${err.エラーメッセージ || '-'}</td>
        <td style="padding: 8px; text-align: center;"><span style="background: rgba(255,255,255,0.1); padding: 3px 6px; border-radius: 3px; color: ${priorityColor}; font-weight: 600; font-size: 12px;">${err.重要度 || '-'}</span></td>
        <td style="padding: 8px; text-align: center;"><span style="background: ${statusBg}; padding: 3px 6px; border-radius: 3px; color: ${statusColor}; font-weight: 600; font-size: 12px;">${err.ステータス || '-'}</span></td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${err.発生日時 ? new Date(err.発生日時).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 8px; color: var(--text);">${err.対応者ID || '-'}</td>
        <td style="padding: 8px; text-align: center;"><button class="action-btn secondary detail-btn" data-id="${err.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button></td>
      </tr>`;
    }).join("");

    updateKpis(errors);
  }

  // 3. 詳細パネル表示
  function showDetail(errorId) {
    const error = allErrors.find(e => e.id === errorId);
    if (!error) return;

    selectedErrorId = errorId;
    detailContent.innerHTML = `
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">エラーID</div>
        <div style="color: var(--text); font-family: monospace; font-size: 12px;">${error.id || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">受注番号</div>
        <div style="color: var(--text);">${error.受注番号 || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">エラー分類</div>
        <div style="color: var(--text);">${error.エラー種別 || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">エラーメッセージ</div>
        <div style="color: var(--text); word-break: break-word;">${error.エラーメッセージ || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">エラー詳細</div>
        <div style="color: var(--text); word-break: break-word; background: rgba(0,0,0,0.25); padding: 6px; border-radius: 3px; font-family: monospace; font-size: 11px; max-height: 100px; overflow-y: auto;">${error.エラー詳細 || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">優先度</div>
        <div style="color: var(--text);">${error.重要度 || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">ステータス</div>
        <div style="color: var(--text);">${error.ステータス || '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">発生日時</div>
        <div style="color: var(--text);">${error.発生日時 ? new Date(error.発生日時).toLocaleString('ja-JP') : '-'}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">対応コメント</div>
        <div style="color: var(--text); word-break: break-word; background: rgba(0,0,0,0.25); padding: 6px; border-radius: 3px; min-height: 40px;">${error.対応コメント || '（未入力）'}</div>
      </div>
    `;
    detailModal.removeAttribute("hidden");
  }

  // 4. 初期データ読み込み
  async function loadErrors() {
    const rows = await window.aivicApi.list(0);
    allErrors = rows || [];
    renderRows(allErrors);
  }

  // 5. フィルタ適用
  function applyFilters() {
    const responsible = container.querySelector("#filter-responsible").value;
    const category = container.querySelector("#filter-category").value;
    const priority = container.querySelector("#filter-priority").value;
    const status = container.querySelector("#filter-status").value;
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;

    let filtered = allErrors;

    if (responsible) {
      filtered = filtered.filter(e => e.対応者ID === responsible || e.部門 === responsible);
    }
    if (category) {
      filtered = filtered.filter(e => e.エラー種別 === category);
    }
    if (priority) {
      filtered = filtered.filter(e => e.重要度 === priority);
    }
    if (status) {
      filtered = filtered.filter(e => e.ステータス === status);
    }
    if (dateFrom) {
      filtered = filtered.filter(e => e.発生日時 >= dateFrom);
    }
    if (dateTo) {
      filtered = filtered.filter(e => e.発生日時 <= dateTo + "T23:59:59");
    }

    renderRows(filtered);
  }

  // 6. イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#filter-responsible").addEventListener("change", applyFilters);
  container.querySelector("#filter-category").addEventListener("change", applyFilters);
  container.querySelector("#filter-priority").addEventListener("change", applyFilters);
  container.querySelector("#filter-status").addEventListener("change", applyFilters);

  container.querySelector("#close-detail").addEventListener("click", () => {
    detailModal.setAttribute("hidden", "");
  });

  container.querySelector("#btn-assign").addEventListener("click", async () => {
    if (!selectedErrorId) return;
    await window.aivicApi.update(0, selectedErrorId, { ステータス: "対応中" });
    await loadErrors();
    detailModal.setAttribute("hidden", "");
  });

  container.querySelector("#btn-resolve").addEventListener("click", async () => {
    if (!selectedErrorId) return;
    await window.aivicApi.update(0, selectedErrorId, { ステータス: "解決済み" });
    await loadErrors();
    detailModal.setAttribute("hidden", "");
  });

  container.querySelector("#btn-comment").addEventListener("click", () => {
    commentModal.removeAttribute("hidden");
  });

  container.querySelector("#btn-cancel-comment").addEventListener("click", () => {
    commentModal.setAttribute("hidden", "");
    container.querySelector("#comment-text").value = "";
  });

  container.querySelector("#btn-save-comment").addEventListener("click", async () => {
    const comment = container.querySelector("#comment-text").value;
    if (!selectedErrorId || !comment.trim()) return;
    await window.aivicApi.update(0, selectedErrorId, { 対応コメント: comment });
    await loadErrors();
    commentModal.setAttribute("hidden", "");
    container.querySelector("#comment-text").value = "";
    showDetail(selectedErrorId);
  });

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  // CSVエクスポート
  container.querySelector("[data-testid='export-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["エラーID", "受注番号", "エラー分類", "エラー内容", "優先度", "ステータス", "発生日時", "責任者"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.id || "",
        r.受注番号 || "",
        r.エラー種別 || "",
        `"${(r.エラーメッセージ || "").replace(/"/g, '""')}"`,
        r.重要度 || "",
        r.ステータス || "",
        r.発生日時 || "",
        r.対応者ID || ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `error-notification-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 更新ボタン
  container.querySelector("[data-testid='refresh-button']").addEventListener("click", loadErrors);

  // 初期ロード
  loadErrors();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#integration-tbody");
  const errorDetailPanel = container.querySelector("#error-detail-panel");
  const errorDetailTemplate = container.querySelector("#error-detail-template");

  let allRows = [];
  let selectedRowId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    updateKPIs(rows);

    tbody.innerHTML = rows.map(r => {
      const statusColor = r.処理ステータス === "成功" ? "#4ade80" : 
                          r.処理ステータス === "失敗" ? "#f87171" : 
                          r.処理ステータス === "部分成功" ? "#fb923c" : "#9fb0d1";
      return `
        <tr data-id="${r.連携履歴ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" 
            onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 0.5rem; color: var(--text);">${r.実行開始日時 ? new Date(r.実行開始日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 0.5rem; color: var(--text);">${r.連携種別 || '-'}</td>
          <td style="padding: 0.5rem; color: ${statusColor}; font-weight: 600;">${r.処理ステータス || '-'}</td>
          <td style="padding: 0.5rem; text-align: center; color: var(--text);">${r.送信データ件数 || 0}</td>
          <td style="padding: 0.5rem; text-align: center; color: #4ade80; font-weight: 600;">${r.成功件数 || 0}</td>
          <td style="padding: 0.5rem; text-align: center; color: #f87171; font-weight: 600;">${r.失敗件数 || 0}</td>
          <td style="padding: 0.5rem; text-align: center; color: var(--text);">${r.処理時間秒 ? r.処理時間秒 + 's' : '-'}</td>
        </tr>
      `;
    }).join("");
  }

  // KPI 更新関数
  function updateKPIs(rows) {
    const total = rows.length;
    const success = rows.filter(r => r.処理ステータス === "成功").length;
    const error = rows.filter(r => r.処理ステータス === "失敗").length;
    const warning = rows.filter(r => r.処理ステータス === "部分成功").length;

    container.querySelector("[data-testid='kpi-total']").textContent = total;
    container.querySelector("[data-testid='kpi-success']").textContent = success;
    container.querySelector("[data-testid='kpi-error']").textContent = error;
    container.querySelector("[data-testid='kpi-warning']").textContent = warning;
  }

  // エラー詳細表示関数
  function showErrorDetail(rowId) {
    const row = allRows.find(r => r.連携履歴ID === rowId);
    if (!row) return;

    selectedRowId = rowId;
    const clone = errorDetailTemplate.cloneNode(true);
    clone.style.display = "block";

    clone.querySelector(".detail-integration-id").textContent = row.連携履歴ID || '-';
    clone.querySelector(".detail-order-id").textContent = row.受注データID || '-';
    clone.querySelector(".detail-error-code").textContent = row.エラーコード || '-';
    clone.querySelector(".detail-error-message").textContent = row.エラー詳細 || row.エラーメッセージ || '-';

    const severityColor = row.重要度 === "CRITICAL" ? "#f87171" : 
                          row.重要度 === "ERROR" ? "#fb923c" : 
                          row.重要度 === "WARNING" ? "#fbbf24" : "#9fb0d1";
    const severityEl = clone.querySelector(".detail-severity");
    severityEl.textContent = row.重要度 || '-';
    severityEl.style.color = severityColor;

    clone.querySelector(".detail-created-at").textContent = row.作成日時 ? new Date(row.作成日時).toLocaleString('ja-JP') : '-';
    clone.querySelector(".detail-status").textContent = row.ステータス || '未対応';

    errorDetailPanel.innerHTML = "";
    errorDetailPanel.appendChild(clone);
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const dateFrom = container.querySelector("[data-testid='filter-date-from']").value;
    const dateTo = container.querySelector("[data-testid='filter-date-to']").value;
    const status = container.querySelector("[data-testid='filter-status']").value;
    const orderId = container.querySelector("[data-testid='search-order-id']").value.toLowerCase();
    const errorCategory = container.querySelector("[data-testid='filter-error-category']").value;
    const responsible = container.querySelector("[data-testid='filter-responsible']").value;

    let rows = tables[0].records || [];

    if (dateFrom) rows = rows.filter(r => new Date(r.実行開始日時) >= new Date(dateFrom));
    if (dateTo) rows = rows.filter(r => new Date(r.実行開始日時) <= new Date(dateTo + "T23:59:59"));
    if (status) rows = rows.filter(r => r.処理ステータス === status);
    if (orderId) rows = rows.filter(r => (r.受注データID || "").toLowerCase().includes(orderId));
    if (errorCategory) rows = rows.filter(r => (r.エラー種別 || "").includes(errorCategory));
    if (responsible) rows = rows.filter(r => (r.責任者 || "").includes(responsible));

    renderRows(rows);
    errorDetailPanel.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 1rem 0;">一覧から行を選択してください</div>';
  });

  // 4. 更新ボタン
  container.querySelector("[data-testid='refresh-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) renderRows(rows);
  });

  // 5. 行クリックでエラー詳細表示
  tbody.addEventListener("click", (e) => {
    const tr = e.target.closest("tr");
    if (tr) {
      const rowId = tr.dataset.id;
      showErrorDetail(rowId);
    }
  });

  // 6. 再処理ボタン
  errorDetailPanel.addEventListener("click", async (e) => {
    if (e.target.closest("[data-testid='detail-retry-button']")) {
      if (!selectedRowId) return;
      if (!confirm("この連携を再処理しますか？")) return;

      // 再処理 API 呼び出し（実装例）
      const result = await window.aivicApi.update(0, selectedRowId, { ステータス: "再処理中" });
      if (result) {
        alert("再処理をスケジュールしました");
        const rows = await window.aivicApi.list(0);
        if (rows) renderRows(rows);
      }
    }
  });
}

function(container, apiUrl, tables) {
  const uploadZone = container.querySelector("#upload-zone");
  const fileInput = container.querySelector("#file-input");
  const fileName = container.querySelector("#file-name");
  const btnBrowse = container.querySelector("#btn-browse");
  const btnExecute = container.querySelector("#btn-execute-validation");
  const btnSendNotif = container.querySelector("#btn-send-notification");
  const btnLoadRules = container.querySelector("#btn-load-rules");
  const btnTemplateDownload = container.querySelector("#btn-template-download");
  const rulesList = container.querySelector("#rules-list");
  const errorTbody = container.querySelector("#error-tbody");
  const errorDetail = container.querySelector("#error-detail");
  const progressContainer = container.querySelector("#progress-container");
  const progressIdle = container.querySelector("#progress-idle");
  const progressBar = container.querySelector("#progress-bar");
  const progressText = container.querySelector("#progress-text");
  const resultSuccess = container.querySelector("#result-success");
  const resultWarning = container.querySelector("#result-warning");
  const resultError = container.querySelector("#result-error");

  let uploadedData = null;
  let validationResults = [];
  let selectedErrorIndex = -1;

  // ===== 1. ルール読込 =====
  btnLoadRules.addEventListener("click", async () => {
    const rules = await window.aivicApi.list(3); // バリデーションルール
    if (!rules) return;
    rulesList.innerHTML = rules.slice(0, 10).map((r, i) => `
      <div style="padding: 4px; border-bottom: 1px solid rgba(255,255,255,0.08); font-size: 11px; cursor: pointer; display: flex; justify-content: space-between; align-items: center;" data-rule-id="${r.id}">
        <span style="color: var(--text);">${r.ルール名 || "ルール"}</span>
        <span style="color: var(--text-muted); font-size: 10px;">${r.ルールタイプ || ""}</span>
      </div>
    `).join("");
  });

  // ===== 2. テンプレートDL =====
  btnTemplateDownload.addEventListener("click", () => {
    const headers = ["受注ID", "受注番号", "顧客ID", "受注日", "納期", "受注金額", "ステータス"];
    const csv = "\uFEFF" + headers.join(",") + "\n";
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "validation_template.csv";
    link.click();
  });

  // ===== 3. ファイル選択 =====
  btnBrowse.addEventListener("click", () => fileInput.click());
  fileInput.addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (!file) return;
    fileName.textContent = `📄 ${file.name}`;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target.result;
      const lines = text.trim().split("\n");
      const headers = lines[0].split(",");
      uploadedData = lines.slice(1).map(line => {
        const values = line.split(",");
        const obj = {};
        headers.forEach((h, i) => obj[h.trim()] = values[i]?.trim() || "");
        return obj;
      });
    };
    reader.readAsText(file);
  });

  // ===== 4. ドラッグ&ドロップ =====
  uploadZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadZone.style.background = "rgba(255,165,0,0.15)";
    uploadZone.style.borderColor = "rgba(255,165,0,0.5)";
  });
  uploadZone.addEventListener("dragleave", () => {
    uploadZone.style.background = "rgba(0,0,0,0.2)";
    uploadZone.style.borderColor = "rgba(255,255,255,0.25)";
  });
  uploadZone.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadZone.style.background = "rgba(0,0,0,0.2)";
    uploadZone.style.borderColor = "rgba(255,255,255,0.25)";
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      fileInput.files = files;
      const evt = new Event("change", { bubbles: true });
      fileInput.dispatchEvent(evt);
    }
  });

  // ===== 5. 検証実行 =====
  btnExecute.addEventListener("click", async () => {
    if (!uploadedData || uploadedData.length === 0) {
      alert("テストデータをアップロードしてください");
      return;
    }
    progressIdle.style.display = "none";
    progressContainer.style.display = "block";
    validationResults = [];
    let successCount = 0, warningCount = 0, errorCount = 0;

    for (let i = 0; i < uploadedData.length; i++) {
      const row = uploadedData[i];
      const progress = Math.round((i / uploadedData.length) * 100);
      progressBar.style.width = progress + "%";
      progressText.textContent = progress + "%";

      // シミュレーション：ルール適用
      const hasError = Math.random() > 0.7;
      const hasWarning = Math.random() > 0.8 && !hasError;
      if (hasError) {
        errorCount++;
        validationResults.push({
          id: `err-${i}`,
          code: `VAL_${String(i + 1).padStart(3, "0")}`,
          message: `受注番号 ${row["受注番号"]} の金額が無効です`,
          severity: "ERROR",
          field: "受注金額",
          value: row["受注金額"],
          type: "バリデーション"
        });
      } else if (hasWarning) {
        warningCount++;
        validationResults.push({
          id: `warn-${i}`,
          code: `WARN_${String(i + 1).padStart(3, "0")}`,
          message: `受注日が過去日付です`,
          severity: "WARNING",
          field: "受注日",
          value: row["受注日"],
          type: "バリデーション"
        });
      } else {
        successCount++;
      }
      await new Promise(r => setTimeout(r, 50));
    }

    progressBar.style.width = "100%";
    progressText.textContent = "100%";
    resultSuccess.textContent = successCount;
    resultWarning.textContent = warningCount;
    resultError.textContent = errorCount;

    renderErrors(validationResults);
  });

  // ===== 6. エラー一覧描画 =====
  function renderErrors(errors) {
    if (errors.length === 0) {
      errorTbody.innerHTML = `<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">エラーはありません</td></tr>`;
      return;
    }
    errorTbody.innerHTML = errors.map((e, i) => `
      <tr style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); hover: background: rgba(255,165,0,0.1);" data-error-index="${i}">
        <td style="padding: 6px; color: var(--text);">${e.code}</td>
        <td style="padding: 6px; color: var(--text); font-size: 10px;">${e.message.substring(0, 30)}...</td>
        <td style="padding: 6px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: ${e.severity === "ERROR" ? "rgba(255,107,107,0.3); color: #ff6b6b;" : "rgba(250,204,21,0.3); color: #facc15;"};">${e.severity}</span>
        </td>
      </tr>
    `).join("");
    errorTbody.addEventListener("click", (e) => {
      const row = e.target.closest("tr");
      if (row) {
        const idx = parseInt(row.dataset.errorIndex);
        selectedErrorIndex = idx;
        const err = errors[idx];
        errorDetail.innerHTML = `
          <div style="color: var(--text); margin-bottom: 6px;"><strong>コード:</strong> ${err.code}</div>
          <div style="color: var(--text); margin-bottom: 6px;"><strong>メッセージ:</strong> ${err.message}</div>
          <div style="color: var(--text); margin-bottom: 6px;"><strong>フィールド:</strong> ${err.field}</div>
          <div style="color: var(--text); margin-bottom: 6px;"><strong>値:</strong> ${err.value}</div>
          <div style="color: var(--text-muted); font-size: 10px;"><strong>種別:</strong> ${err.type}</div>
        `;
      }
    });
  }

  // ===== 7. タブフィルタ =====
  const tabAll = container.querySelector("#tab-all-errors");
  const tabVal = container.querySelector("#tab-validation-errors");
  const tabSys = container.querySelector("#tab-system-errors");
  const tabCrit = container.querySelector("#tab-critical-errors");

  tabAll.addEventListener("click", () => {
    tabAll.style.borderBottom = "2px solid var(--primary)";
    tabVal.style.borderBottom = "none";
    tabSys.style.borderBottom = "none";
    tabCrit.style.borderBottom = "none";
    renderErrors(validationResults);
  });
  tabVal.addEventListener("click", () => {
    tabAll.style.borderBottom = "none";
    tabVal.style.borderBottom = "2px solid var(--primary)";
    tabSys.style.borderBottom = "none";
    tabCrit.style.borderBottom = "none";
    renderErrors(validationResults.filter(e => e.type === "バリデーション"));
  });
  tabSys.addEventListener("click", () => {
    tabAll.style.borderBottom = "none";
    tabVal.style.borderBottom = "none";
    tabSys.style.borderBottom = "2px solid var(--primary)";
    tabCrit.style.borderBottom = "none";
    renderErrors(validationResults.filter(e => e.type === "システム"));
  });
  tabCrit.addEventListener("click", () => {
    tabAll.style.borderBottom = "none";
    tabVal.style.borderBottom = "none";
    tabSys.style.borderBottom = "none";
    tabCrit.style.borderBottom = "2px solid var(--primary)";
    renderErrors(validationResults.filter(e => e.severity === "ERROR"));
  });

  // ===== 8. 通知送信 =====
  btnSendNotif.addEventListener("click", async () => {
    const responsible = container.querySelector("#responsible-select").value;
    const notifyEmail = container.querySelector("#notify-email").checked;
    const notifySlack = container.querySelector("#notify-slack").checked;

    if (!responsible) {
      alert("責任者を選択してください");
      return;
    }
    if (!notifyEmail && !notifySlack) {
      alert("通知チャネルを選択してください");
      return;
    }

    const notifData = {
      responsible_id: responsible,
      channels: (notifyEmail ? ["email"] : []).concat(notifySlack ? ["slack"] : []),
      error_count: validationResults.length,
      timestamp: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(11, notifData); // 通知履歴
    if (saved) {
      alert("通知を送信しました");
    }
  });

  // 初期化
  renderErrors([]);
}
